     9→import Combine
    10→import Foundation
    11→import MatrixRustSDK
    12→
    13→private final class WeakNotificationSettingsProxy: NotificationSettingsDelegate {
    14→    private weak var proxy: NotificationSettingsProxy?
    15→    
    16→    init(proxy: NotificationSettingsProxy) {
    17→        self.proxy = proxy
    18→    }
    19→    
    20→    // MARK: - NotificationSettingsDelegate
    21→    
    22→    func settingsDidChange() {
    23→        Task {
    24→            await proxy?.settingsDidChange()
    25→        }
    26→    }
    27→}
    28→
    29→final class NotificationSettingsProxy: NotificationSettingsProxyProtocol {
    30→    private(set) var notificationSettings: MatrixRustSDK.NotificationSettingsProtocol
    31→    
    32→    let callbacks = PassthroughSubject<NotificationSettingsProxyCallback, Never>()
    33→
    34→    init(notificationSettings: MatrixRustSDK.NotificationSettingsProtocol) {
    35→        self.notificationSettings = notificationSettings
    36→        notificationSettings.setDelegate(delegate: WeakNotificationSettingsProxy(proxy: self))
    37→    }
    38→    
    39→    func getNotificationSettings(roomId: String, isEncrypted: Bool, isOneToOne: Bool) async throws -> RoomNotificationSettingsProxyProtocol {
    40→        let roomMotificationSettings = try await notificationSettings.getRoomNotificationSettings(roomId: roomId, isEncrypted: isEncrypted, isOneToOne: isOneToOne)
    41→        return RoomNotificationSettingsProxy(roomNotificationSettings: roomMotificationSettings)
    42→    }
    43→    
    44→    func setNotificationMode(roomId: String, mode: RoomNotificationModeProxy) async throws {
    45→        try await notificationSettings.setRoomNotificationMode(roomId: roomId, mode: mode.roomNotificationMode)
    46→        await updatedSettings()
    47→    }
    48→    
    49→    func getUserDefinedRoomNotificationMode(roomId: String) async throws -> RoomNotificationModeProxy? {
    50→        let roomNotificationMode = try await notificationSettings.getUserDefinedRoomNotificationMode(roomId: roomId)
    51→        return roomNotificationMode.flatMap { RoomNotificationModeProxy.from(roomNotificationMode: $0) }
    52→    }
    53→    
    54→    func getDefaultRoomNotificationMode(isEncrypted: Bool, isOneToOne: Bool) async -> RoomNotificationModeProxy {
    55→        let roomNotificationMode = await notificationSettings.getDefaultRoomNotificationMode(isEncrypted: isEncrypted, isOneToOne: isOneToOne)
    56→        return RoomNotificationModeProxy.from(roomNotificationMode: roomNotificationMode)
    57→    }
    58→
    59→    func setDefaultRoomNotificationMode(isEncrypted: Bool, isOneToOne: Bool, mode: RoomNotificationModeProxy) async throws {
    60→        do {
    61→            try await notificationSettings.setDefaultRoomNotificationMode(isEncrypted: isEncrypted, isOneToOne: isOneToOne, mode: mode.roomNotificationMode)
    62→        } catch NotificationSettingsError.RuleNotFound(let ruleId) {
    63→            // `setDefaultRoomNotificationMode` updates multiple rules including unstable rules (e.g. the polls push rules defined in the MSC3930)
    64→            // since production home servers may not have these rules yet, we drop the RuleNotFound error
    65→            MXLog.warning("Unable to find the rule: \(ruleId)")
    66→            return
    67→        }
    68→
    69→        await updatedSettings()
    70→    }
    71→    
    72→    func restoreDefaultNotificationMode(roomId: String) async throws {
    73→        try await notificationSettings.restoreDefaultRoomNotificationMode(roomId: roomId)
    74→        await updatedSettings()
    75→    }
    76→       
    77→    func unmuteRoom(roomId: String, isEncrypted: Bool, isOneToOne: Bool) async throws {
    78→        try await notificationSettings.unmuteRoom(roomId: roomId, isEncrypted: isEncrypted, isOneToOne: isOneToOne)
    79→        await updatedSettings()
    80→    }
    81→    
    82→    func isRoomMentionEnabled() async throws -> Bool {
    83→        try await notificationSettings.isRoomMentionEnabled()
    84→    }
    85→    
    86→    func setRoomMentionEnabled(enabled: Bool) async throws {
    87→        try await notificationSettings.setRoomMentionEnabled(enabled: enabled)
    88→        await updatedSettings()
    89→    }
    90→    
    91→    func isCallEnabled() async throws -> Bool {
    92→        try await notificationSettings.isCallEnabled()
    93→    }
    94→    
    95→    func setCallEnabled(enabled: Bool) async throws {
    96→        try await notificationSettings.setCallEnabled(enabled: enabled)
    97→        await updatedSettings()
    98→    }
    99→    
   100→    func isInviteForMeEnabled() async throws -> Bool {
   101→        try await notificationSettings.isInviteForMeEnabled()
   102→    }
   103→    
   104→    func setInviteForMeEnabled(enabled: Bool) async throws {
   105→        try await notificationSettings.setInviteForMeEnabled(enabled: enabled)
   106→        await updatedSettings()
   107→    }
   108→    
   109→    func getRoomsWithUserDefinedRules() async throws -> [String] {
   110→        await notificationSettings.getRoomsWithUserDefinedRules(enabled: true)
   111→    }
   112→    
   113→    func canPushEncryptedEventsToDevice() async -> Bool {
   114→        await notificationSettings.canPushEncryptedEventToDevice()
   115→    }
   116→    
   117→    // MARK: - Private
   118→    
   119→    func updatedSettings() async {
   120→        // The timeout avoids having to wait indefinitely. This can happen when setting a mode that is already the current mode,
   121→        // as in this case no API call is made by the RustSDK and the push rules are therefore not updated.
   122→        _ = await callbacks
   123→            .timeout(.seconds(2.0), scheduler: DispatchQueue.main, options: nil, customError: nil)
   124→            .values.first { $0 == .settingsDidChange }
   125→    }
   126→    
   127→    @MainActor
   128→    func settingsDidChange() {
   129→        callbacks.send(.settingsDidChange)
   130→    }
   131→}
