    65→    var pinnedEventsActionState = RoomDetailsScreenPinnedEventsActionState.loading
    66→    
    67→    var knockingEnabled = false
    68→    var isKnockableRoom = false
    69→    var knockRequestsCount = 0
    70→    
    71→    var reportRoomEnabled = false
