    87→    }
    88→
    89→    var bindings: RoomDetailsScreenViewStateBindings
    90→
    91→    var dmRecipientInfo: DMRecipientInfo?
    92→    var accountOwner: RoomMemberDetails?
    93→    
    94→    var shortcuts: [RoomDetailsScreenViewShortcut] {
    95→        var shortcuts: [RoomDetailsScreenViewShortcut] = [.mute]
    96→        if !ProcessInfo.processInfo.isiOSAppOnMac, canJoinCall {
    97→            shortcuts.append(.call)
    98→        }
    99→        if dmRecipientInfo == nil, canInviteUsers {
   100→            shortcuts.append(.invite)
   101→        }
   102→        if let permalink = dmRecipientInfo?.member.permalink {
   103→            shortcuts.append(.share(link: permalink))
   104→        } else if let permalink {
   105→            shortcuts.append(.share(link: permalink))
   106→        }
   107→        return shortcuts
   108→    }
   109→    
   110→    var isProcessingMuteToggleAction = false
   111→    
   112→    var areNotificationsMuted: Bool {
   113→        if case .loaded(let settings) = notificationSettingsState {
   114→            return settings.mode == .mute
   115→        }
   116→        return false
   117→    }
   118→    
   119→    var notificationShortcutButtonTitle: String {
   120→        areNotificationsMuted ? L10n.commonUnmute : L10n.commonMute
