   128→struct RoomDetailsScreenViewStateBindings {
   129→    struct IgnoreUserAlertItem: AlertProtocol, Equatable {
   130→        enum Action {
   131→            case ignore
   132→            case unignore
   133→        }
   134→
   135→        let action: Action
   136→        let cancelTitle = L10n.actionCancel
   137→
   138→        var title: String {
   139→            switch action {
   140→            case .ignore: return L10n.screenDmDetailsBlockUser
   141→            case .unignore: return L10n.screenDmDetailsUnblockUser
   142→            }
   143→        }
   144→
   145→        var confirmationTitle: String {
   146→            switch action {
   147→            case .ignore: return L10n.screenDmDetailsBlockAlertAction
   148→            case .unignore: return L10n.screenDmDetailsUnblockAlertAction
   149→            }
   150→        }
   151→
   152→        var description: String {
   153→            switch action {
   154→            case .ignore: return L10n.screenDmDetailsBlockAlertDescription
   155→            case .unignore: return L10n.screenDmDetailsUnblockAlertDescription
   156→            }
   157→        }
   158→
   159→        var viewAction: RoomDetailsScreenViewAction {
   160→            switch action {
   161→            case .ignore: return .ignoreConfirmed
   162→            case .unignore: return .unignoreConfirmed
   163→            }
   164→        }
   165→    }
   166→    
   167→    var isFavourite = false
   168→
   169→    /// Information describing the currently displayed alert.
   170→    var alertInfo: AlertInfo<RoomDetailsScreenErrorType>?
   171→    var leaveRoomAlertItem: LeaveRoomAlertItem?
   172→    var ignoreUserRoomAlertItem: IgnoreUserAlertItem?
   173→    
   174→    /// A media item that will be previewed with QuickLook.
   175→    var mediaPreviewItem: MediaPreviewItem?
   176→    
   177→    /// The view model used to display the leave space sheet, will only be used if the room is a space.
   178→    var leaveSpaceViewModel: LeaveSpaceViewModel?
   179→}
   180→
   181→struct LeaveRoomAlertItem: AlertProtocol {
   182→    enum RoomState {
   183→        case empty
   184→        case `public`
   185→        case `private`
   186→    }
   187→
   188→    let roomID: String
   189→    let isDM: Bool
   190→    let state: RoomState
   191→    let confirmationTitle = L10n.actionLeave
   192→    let cancelTitle = L10n.actionCancel
   193→    
   194→    var title: String {
   195→        isDM ? L10n.actionLeaveConversation : L10n.actionLeaveRoom
   196→    }
   197→
   198→    var subtitle: String {
   199→        switch state {
   200→        case .empty: return L10n.leaveRoomAlertEmptySubtitle
   201→        case .private: return isDM ? L10n.leaveConversationAlertSubtitle : L10n.leaveRoomAlertPrivateSubtitle
   202→        case .public: return L10n.leaveRoomAlertSubtitle
   203→        }
   204→    }
   205→}
