   242→enum RoomDetailsNotificationSettingsState {
   243→    case loading
   244→    case loaded(settings: RoomNotificationSettingsProxyProtocol)
   245→    case error
   246→}
   247→
   248→extension RoomDetailsNotificationSettingsState {
   249→    var label: String {
   250→        switch self {
   251→        case .loading:
   252→            return L10n.commonLoading
   253→        case .loaded(let settings):
   254→            if settings.isDefault {
   255→                return L10n.screenRoomDetailsNotificationModeDefault
   256→            } else {
   257→                return L10n.screenRoomDetailsNotificationModeCustom
   258→            }
   259→        case .error:
   260→            return L10n.commonError
   261→        }
   262→    }
   263→    
   264→    var isLoading: Bool {
   265→        if case .loading = self {
   266→            return true
   267→        }
   268→        return false
   269→    }
   270→    
   271→    var isLoaded: Bool {
   272→        if case .loaded = self {
   273→            return true
   274→        }
   275→        return false
   276→    }
   277→    
   278→    /// Returns `true` when the settings are loaded and `isDefault` is false.
   279→    var isCustom: Bool {
   280→        guard case let .loaded(settings) = self else { return false }
   281→        return !settings.isDefault
   282→    }
   283→    
   284→    var isError: Bool {
   285→        if case .error = self {
   286→            return true
   287→        }
   288→        return false
   289→    }
   290→}
   291→
   292→enum RoomDetailsScreenErrorType: Hashable {
   293→    /// A specific error message shown in an alert.
   294→    case alert
   295→    /// Leaving room has failed..
   296→    case unknown
   297→    /// Last owner
   298→    case lastOwner
   299→}
   300→
   301→enum RoomDetailsScreenPinnedEventsActionState {
   302→    case loading
   303→    case loaded(numberOfItems: Int)
   304→    
   305→    var count: String {
   306→        switch self {
   307→        case .loading:
   308→            return ""
   309→        case .loaded(let numberOfItems):
   310→            return "\(numberOfItems)"
   311→        }
   312→    }
   313→    
   314→    var isLoading: Bool {
   315→        switch self {
   316→        case .loading:
   317→            return true
   318→        default:
   319→            return false
   320→        }
   321→    }
   322→}
