    12→struct RoomDetailsScreen: View {
    13→    @Bindable var context: RoomDetailsScreenViewModel.Context
    14→    
    15→    @State private var isTopicExpanded = false
    16→    
    17→    var body: some View {
    18→        Form {
    19→            roomHeaderSection
    20→
    21→            topicSection
    22→            
    23→            configurationSection
    24→            
    25→            if context.viewState.dmRecipientInfo == nil {
    26→                peopleSection
    27→            }
    28→
    29→            aboutSection
    30→
    31→            securitySection
    32→
    33→            if let recipient = context.viewState.dmRecipientInfo?.member {
    34→                ignoreUserSection(user: recipient)
    35→            }
    36→            
    37→            leaveRoomSection
    38→        }
    39→        .compoundList()
    40→        .alert(item: $context.alertInfo)
    41→        .alert(item: $context.leaveRoomAlertItem,
    42→               actions: leaveRoomAlertActions,
    43→               message: leaveRoomAlertMessage)
    44→        .alert(item: $context.ignoreUserRoomAlertItem,
    45→               actions: blockUserAlertActions,
    46→               message: blockUserAlertMessage)
    47→        .toolbar {
    48→            ToolbarItem(placement: .navigationBarTrailing) {
    49→                if context.viewState.canEditBaseInfo {
    50→                    Button(L10n.actionEdit) {
    51→                        context.send(viewAction: .processTapEdit)
    52→                    }
    53→                }
    54→            }
    55→        }
    56→        .navigationTitle(L10n.screenRoomDetailsTitle)
    57→        .navigationBarTitleDisplayMode(.inline)
    58→        .track(screen: .RoomDetails)
    59→        .interactiveQuickLook(item: $context.mediaPreviewItem, allowEditing: false)
    60→    }
    61→    
    62→    // MARK: - Private
    63→    
    64→    private var roomHeaderSection: some View {
    65→        AvatarHeaderView(room: context.viewState.details,
    66→                         avatarSize: .room(on: .details),
    67→                         mediaProvider: context.mediaProvider) { url in
    68→            context.send(viewAction: .displayAvatar(url))
    69→        } footer: {
    70→            if !context.viewState.shortcuts.isEmpty {
    71→                headerSectionShortcuts
    72→            }
    73→        }
    74→        .accessibilityIdentifier(A11yIdentifiers.roomDetailsScreen.avatar)
    75→    }
    76→    
    77→    private var headerSectionShortcuts: some View {
    78→        HStack(spacing: 8) {
    79→            ForEach(context.viewState.shortcuts, id: \.self) { shortcut in
    80→                switch shortcut {
    81→                case .mute:
    82→                    toggleMuteButton
    83→                case .share(let permalink):
    84→                    ShareLink(item: permalink) {
    85→                        CompoundIcon(\.shareIos)
    86→                    }
    87→                    .buttonStyle(FormActionButtonStyle(title: L10n.actionShare))
    88→                case .call:
    89→                    Button {
    90→                        context.send(viewAction: .processTapCall)
    91→                    } label: {
    92→                        CompoundIcon(\.videoCall)
    93→                    }
    94→                    .buttonStyle(FormActionButtonStyle(title: L10n.actionCall))
    95→                case .invite:
    96→                    Button {
    97→                        context.send(viewAction: .processTapInvite)
    98→                    } label: {
    99→                        CompoundIcon(\.userAdd)
   100→                    }

