    13→struct HomeScreenRoomCell: View {
    14→    @Environment(\.dynamicTypeSize) var dynamicTypeSize
    15→    @Environment(\.redactionReasons) private var redactionReasons
    16→    
    17→    let room: HomeScreenRoom
    18→    let isSelected: Bool
    19→    let mediaProvider: MediaProviderProtocol!
    20→    let action: (HomeScreenViewAction) -> Void
    21→    
    22→    private let verticalInsets = 12.0
    23→    private let horizontalInsets = 16.0
    24→    
    25→    var body: some View {
    26→        Button {
    27→            if let roomID = room.roomID {
    28→                action(.selectRoom(roomIdentifier: roomID))
    29→            }
    30→        } label: {
    31→            HStack(spacing: 16.0) {
    32→                avatar
    33→                
    34→                content
    35→                    .padding(.vertical, verticalInsets)
    36→                    .overlay(alignment: .bottom) {
    37→                        Rectangle()
    38→                            .fill(Color.compound.borderDisabled)
    39→                            .frame(height: 1 / UIScreen.main.scale)
    40→                            .padding(.trailing, -horizontalInsets)
    41→                    }
    42→            }
    43→            .padding(.horizontal, horizontalInsets)
    44→            .accessibilityElement(children: .combine)
    45→        }
    46→        .buttonStyle(HomeScreenRoomCellButtonStyle(isSelected: isSelected))
    47→        .accessibilityIdentifier(A11yIdentifiers.homeScreen.roomName(room.name))
    48→        .accessibilityHidden(redactionReasons.contains(.placeholder) ? true : false)
    49→    }
    50→    
    51→    @ViewBuilder @MainActor
    52→    private var avatar: some View {
    53→        if dynamicTypeSize < .accessibility3 {
    54→            RoomAvatarImage(avatar: room.avatar,
    55→                            avatarSize: .room(on: .chats),
    56→                            mediaProvider: mediaProvider)
    57→                .dynamicTypeSize(dynamicTypeSize < .accessibility1 ? dynamicTypeSize : .accessibility1)
    58→                .accessibilityHidden(true)
    59→        }
    60→    }
    61→    
    62→    private var content: some View {
    63→        VStack(alignment: .leading, spacing: 2) {
    64→            header
    65→            footer
    66→        }
    67→        // Hide the normal content for Skeletons and overlay centre aligned placeholders.
    68→        .opacity(redactionReasons.contains(.placeholder) ? 0 : 1)
    69→        .overlay {
    70→            if redactionReasons.contains(.placeholder) {
    71→                VStack(alignment: .leading, spacing: 2) {
    72→                    header
    73→                    lastMessage
    74→                }
    75→            }
    76→        }
    77→    }
    78→    
    79→    private var header: some View {
    80→        HStack(alignment: .top, spacing: 16) {
    81→            Text(room.name)
    82→                .font(.compound.bodyLGSemibold)
    83→                .foregroundColor(.compound.textPrimary)
    84→                .lineLimit(1)
    85→                .frame(maxWidth: .infinity, alignment: .leading)
    86→            
    87→            if let timestamp = room.timestamp {
    88→                Text(timestamp)
    89→                    .font(room.isHighlighted ? .compound.bodySMSemibold : .compound.bodySM)
    90→                    .foregroundColor(room.isHighlighted ? .compound.textActionAccent : .compound.textSecondary)
