    14→class NotificationSettingsEditScreenViewModel: NotificationSettingsEditScreenViewModelType, NotificationSettingsEditScreenViewModelProtocol {
    15→    private var actionsSubject: PassthroughSubject<NotificationSettingsEditScreenViewModelAction, Never> = .init()
    16→    private let chatType: NotificationSettingsChatType
    17→    private let notificationSettingsProxy: NotificationSettingsProxyProtocol
    18→    private let userSession: UserSessionProtocol
    19→    private let roomSummaryProvider: RoomSummaryProviderProtocol?
    20→    
    21→    // periphery:ignore - cancellable tasks get cancelled when reassigned
    22→    @CancellableTask private var fetchDefaultRoomNotificationModesTask: Task<Void, Error>?
    23→    // periphery:ignore - cancellable tasks get cancelled when reassigned
    24→    @CancellableTask private var updateRoomsWithUserDefinedModeTask: Task<Void, Error>?
    25→    
    26→    var actions: AnyPublisher<NotificationSettingsEditScreenViewModelAction, Never> {
    27→        actionsSubject.eraseToAnyPublisher()
    28→    }
    29→    
    30→    init(chatType: NotificationSettingsChatType, userSession: UserSessionProtocol) {
    31→        let bindings = NotificationSettingsEditScreenViewStateBindings()
    32→        self.chatType = chatType
    33→        self.userSession = userSession
    34→        notificationSettingsProxy = userSession.clientProxy.notificationSettings
    35→        roomSummaryProvider = userSession.clientProxy.roomSummaryProvider
    36→        
    37→        super.init(initialViewState: NotificationSettingsEditScreenViewState(bindings: bindings,
    38→                                                                             strings: NotificationSettingsEditScreenStrings(chatType: chatType)),
    39→                   mediaProvider: userSession.mediaProvider)
    40→        
    41→        setupNotificationSettingsSubscription()
    42→        setupRoomSummaryProviderSubscription()
    43→    }
    44→    
    45→    func fetchInitialContent() {
    46→        fetchDefaultRoomNotificationModes()
    47→        updateRoomsWithUserDefinedMode()
    48→    }
    49→    
    50→    // MARK: - Public
    51→    
    52→    override func process(viewAction: NotificationSettingsEditScreenViewAction) {
    53→        switch viewAction {
    54→        case .setMode(let mode):
    55→            setMode(mode)
    56→        case .selectRoom(let roomIdentifier):
    57→            actionsSubject.send(.requestRoomNotificationSettingsPresentation(roomID: roomIdentifier))
    58→        }
    59→    }
    60→    
    61→    // MARK: - Private
    62→    
    63→    private func setupNotificationSettingsSubscription() {
    64→        notificationSettingsProxy.callbacks
    65→            .receive(on: DispatchQueue.main)
    66→            .sink { [weak self] callback in
    67→                guard let self else { return }
    68→                
    69→                switch callback {
    70→                case .settingsDidChange:
    71→                    self.fetchDefaultRoomNotificationModes()
    72→                    self.updateRoomsWithUserDefinedMode()
    73→                }
    74→            }
    75→            .store(in: &cancellables)
    76→    }
    77→    
    78→    private func fetchDefaultRoomNotificationModes() {
    79→        fetchDefaultRoomNotificationModesTask = Task {
    80→            var mode: RoomNotificationModeProxy?
    81→            let isOneToOne = chatType == .oneToOneChat
    82→            let encrypted_mode = await notificationSettingsProxy.getDefaultRoomNotificationMode(isEncrypted: true, isOneToOne: isOneToOne)
    83→            let unencrypted_mode = await notificationSettingsProxy.getDefaultRoomNotificationMode(isEncrypted: false, isOneToOne: isOneToOne)
    84→            if encrypted_mode == unencrypted_mode {
    85→                mode = encrypted_mode
    86→            }
    87→            let canPushEncryptedEvents = await notificationSettingsProxy.canPushEncryptedEventsToDevice()
    88→            guard !Task.isCancelled else { return }
    89→            
    90→            switch mode {
    91→            case .allMessages:
    92→                state.defaultMode = .allMessages
    93→            case .mentionsAndKeywordsOnly:
    94→                state.defaultMode = .mentionsAndKeywordsOnly
    95→            default:
    96→                state.defaultMode = nil
    97→            }
    98→            state.canPushEncryptedEvents = canPushEncryptedEvents
    99→        }
   100→    }
   101→    
   102→    private func setupRoomSummaryProviderSubscription() {
   103→        guard let roomSummaryProvider else {
   104→            MXLog.error("Room summary provider unavailable")
   105→            return
   106→        }
   107→        
   108→        roomSummaryProvider.roomListPublisher
   109→            .receive(on: DispatchQueue.main)
   110→            .sink { [weak self] _ in
   111→                self?.updateRoomsWithUserDefinedMode()
   112→            }
   113→            .store(in: &cancellables)
   114→    }
   115→    
   116→    private func updateRoomsWithUserDefinedMode() {
   117→        guard let roomSummaryProvider else {
   118→            MXLog.error("Room summary provider unavailable")
   119→            return
   120→        }
   121→        
   122→        updateRoomsWithUserDefinedModeTask = Task {
   123→            let roomsWithUserDefinedRules = try await notificationSettingsProxy.getRoomsWithUserDefinedRules()
   124→            guard !Task.isCancelled else { return }
   125→            
   126→            let filteredRoomsSummary = roomSummaryProvider.roomListPublisher.value.filter { summary in
   127→                roomsWithUserDefinedRules.contains { summary.id == $0 }
   128→            }
   129→            
   130→            var roomsWithUserDefinedMode: [NotificationSettingsEditScreenRoom] = []
   131→            
   132→            for roomSummary in filteredRoomsSummary {
   133→                guard case let .joined(roomProxy) = await userSession.clientProxy.roomForIdentifier(roomSummary.id) else { continue }
   134→                // `isOneToOneRoom` here is not the same as `isDirect` on the room. From the point of view of the push rule, a one-to-one room is a room with exactly two active members.
   135→                let isOneToOneRoom = roomProxy.infoPublisher.value.activeMembersCount == 2
   136→                // display only the rooms we're interested in
   137→                switch chatType {
   138→                case .oneToOneChat where isOneToOneRoom, .groupChat where !isOneToOneRoom:
   139→                    await roomsWithUserDefinedMode.append(buildRoom(with: roomSummary))
   140→                default:
   141→                    break
   142→                }
   143→            }
   144→            
   145→            // Sort the room list
   146→            roomsWithUserDefinedMode.sort { $0.name.localizedCompare($1.name) == .orderedAscending }
   147→            
   148→            state.roomsWithUserDefinedMode = roomsWithUserDefinedMode
   149→        }
   150→    }

