    26→    init(notificationSettingsProxy: NotificationSettingsProxyProtocol, roomProxy: JoinedRoomProxyProtocol, displayAsUserDefinedRoomSettings: Bool) {
    27→        let bindings = RoomNotificationSettingsScreenViewStateBindings()
    28→        self.notificationSettingsProxy = notificationSettingsProxy
    29→        self.roomProxy = roomProxy
    30→        let navigationTitle = displayAsUserDefinedRoomSettings ? roomProxy.infoPublisher.value.displayName : L10n.screenRoomDetailsNotificationTitle
    31→        let customSettingsSectionHeader = displayAsUserDefinedRoomSettings ? L10n.screenRoomNotificationSettingsRoomCustomSettingsTitle : L10n.screenRoomNotificationSettingsCustomSettingsTitle
    32→        super.init(initialViewState: RoomNotificationSettingsScreenViewState(bindings: bindings,
    33→                                                                             displayAsUserDefinedRoomSettings: displayAsUserDefinedRoomSettings,
    34→                                                                             navigationTitle: navigationTitle ?? L10n.screenRoomDetailsNotificationTitle,
    35→                                                                             customSettingsSectionHeader: customSettingsSectionHeader))
    36→        
    37→        setupNotificationSettingsSubscription()
    38→        fetchNotificationSettings()
    39→    }
