    41→    // MARK: - Public
    42→    
    43→    override func process(viewAction: RoomNotificationSettingsScreenViewAction) {
    44→        switch viewAction {
    45→        case .changedAllowCustomSettings:
    46→            toogleCustomSetting()
    47→        case .setCustomMode(let mode):
    48→            setCustomMode(mode)
    49→        case .customSettingFootnoteLinkTapped:
    50→            actionsSubject.send(.openGlobalSettings)
    51→        case .deleteCustomSettingTapped:
    52→            Task { await deleteCustomSetting() }
    53→        }
    54→    }
    55→    
    56→    // MARK: - Private
    57→
    58→    private func setupNotificationSettingsSubscription() {
    59→        notificationSettingsProxy.callbacks
    60→            .receive(on: DispatchQueue.main)
    61→            .sink { [weak self] callback in
    62→                guard let self else { return }
    63→                
    64→                switch callback {
    65→                case .settingsDidChange:
    66→                    self.fetchNotificationSettings()
    67→                }
    68→            }
    69→            .store(in: &cancellables)
    70→    }
    71→    
    72→    private func fetchNotificationSettings() {
    73→        fetchNotificationSettingsTask = Task {
    74→            await fetchRoomNotificationSettings()
    75→        }
    76→    }
    77→    
    78→    private func fetchRoomNotificationSettings() async {
    79→        let isEncrypted = roomProxy.infoPublisher.value.isEncrypted
    80→        
    81→        state.shouldDisplayMentionsOnlyDisclaimer = isEncrypted ? await !notificationSettingsProxy.canPushEncryptedEventsToDevice() : false
    82→        
    83→        do {
    84→            // `isOneToOne` here is not the same as `isDirect` on the room. From the point of view of the push rule, a one-to-one room is a room with exactly two active members.
    85→            let settings = try await notificationSettingsProxy.getNotificationSettings(roomId: roomProxy.id,
    86→                                                                                       isEncrypted: isEncrypted,
    87→                                                                                       isOneToOne: roomProxy.infoPublisher.value.activeMembersCount == 2)
    88→            guard !Task.isCancelled else { return }
    89→            state.notificationSettingsState = .loaded(settings: settings)
    90→            if !state.isRestoringDefaultSetting {
    91→                state.bindings.allowCustomSetting = !settings.isDefault
    92→            }
    93→        } catch {
    94→            state.notificationSettingsState = .error
    95→            displayError(.loadingSettingsFailed)
    96→        }
    97→    }
    98→    
    99→    private func toogleCustomSetting() {
   100→        guard case .loaded(let settings) = state.notificationSettingsState else { return }
   101→        guard state.bindings.allowCustomSetting == settings.isDefault else { return }
   102→        
   103→        if state.bindings.allowCustomSetting {
   104→            setCustomMode(settings.mode)
   105→        } else {
   106→            restoreDefaultSetting()
   107→        }
   108→    }
   109→    
   110→    private func restoreDefaultSetting() {
   111→        state.isRestoringDefaultSetting = true
   112→        Task {
   113→            do {
   114→                try await notificationSettingsProxy.restoreDefaultNotificationMode(roomId: roomProxy.id)
   115→            } catch {
   116→                displayError(.restoreDefaultFailed)
   117→            }
   118→            state.isRestoringDefaultSetting = false
   119→        }
   120→    }
   121→    
   122→    private func setCustomMode(_ mode: RoomNotificationModeProxy) {
   123→        // Check if the new mode is already the current one
   124→        if case .loaded(let currentSettings) = state.notificationSettingsState {
   125→            if !currentSettings.isDefault, currentSettings.mode == mode {
   126→                return
   127→            }
   128→        }
   129→        
   130→        state.pendingCustomMode = mode
   131→        Task {
   132→            do {
   133→                try await notificationSettingsProxy.setNotificationMode(roomId: roomProxy.id, mode: mode)
   134→            } catch {
   135→                displayError(.setModeFailed)
   136→            }
   137→            state.pendingCustomMode = nil
   138→        }
   139→    }
   140→    
   141→    private func displayError(_ type: RoomNotificationSettingsScreenErrorType) {
   142→        switch type {
   143→        case .loadingSettingsFailed:
   144→            state.bindings.alertInfo = AlertInfo(id: type,
   145→                                                 title: L10n.commonError,
   146→                                                 message: L10n.screenRoomNotificationSettingsErrorLoadingSettings)
   147→        case .setModeFailed:
   148→            state.bindings.alertInfo = AlertInfo(id: type,
   149→                                                 title: L10n.commonError,
   150→                                                 message: L10n.screenRoomNotificationSettingsErrorSettingMode)
   151→
   152→        case .restoreDefaultFailed:
   153→            state.bindings.alertInfo = AlertInfo(id: type,
   154→                                                 title: L10n.commonError,
   155→                                                 message: L10n.screenRoomNotificationSettingsErrorRestoringDefault)
   156→        }
   157→    }
   158→    
   159→    private func deleteCustomSetting() async {
   160→        state.deletingCustomSetting = true
   161→        do {
   162→            try await notificationSettingsProxy.restoreDefaultNotificationMode(roomId: roomProxy.id)
   163→            actionsSubject.send(.dismiss)
   164→        } catch {
   165→            displayError(.restoreDefaultFailed)
   166→        }
   167→        state.deletingCustomSetting = false
   168→    }
   169→}
